"""Typed paired view of the decode catalog, generated by generate_decode_selection."""
import hashlib
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EVIDENCE = ROOT / 'policies/kpack_gate_up_selection_v2.json'
OUTPUT = ROOT / 'quactlize/fusion/recipes.inc'
ARCHIVE_SHA = '8c6bc2c2daf1fa48f53b39ad71b4e75578c4c88aeffcfe8ee4a22385f2e2c082'
BASE_SOURCE = '0d7361eac2a3becdd53aa29b8b84d29cdc481fb8'
RECIPE_FIELDS = ('backend', 'split', 'tile_m', 'warps', 'reader', 'variant',
                 'columns', 'values', 'changes', 'hoist', 'fixed_n', 'fixed_k')
REQUEST_FIELDS = ('qtype', 'n', 'k', 'experts', 'tokens', 'mode', 'topk', 'channels',
                  'input_type', 'compute_type', 'output_type', 'round_projection',
                  'row_order', 'consumer', 'consumer_qtype', 'consumer_n')


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def recipe(name, *, backend=0, split=1, tile_m=0, warps=8, reader=0,
           variant=3, columns=4, values=8, changes=0, hoist=0, fixed_n=0, fixed_k=0):
    fields = dict(backend=backend, split=split, tile_m=tile_m, warps=warps, reader=reader,
                  variant=variant, columns=columns, values=values, changes=changes,
                  hoist=hoist, fixed_n=fixed_n, fixed_k=fixed_k)
    return dict(name=name, id=digest(fields)[:16], **fields)


def request(q, n, k, tokens, *, output=None, row_order=0, consumer=None, consumer_qtype=-1, consumer_n=-1):
    indexed = q == 12
    return dict(zip(REQUEST_FIELDS, (q, n, k, 256 if indexed else 1, tokens,
        2 if indexed else 0, 8 if indexed else 1, 1, 1, int(indexed),
        1 if output is None else output, int(indexed), row_order,
        (1 if indexed else 0) if consumer is None else consumer, consumer_qtype, consumer_n)))


def inherited_catalog():
    """Migration snapshot of the old selector and its actual launcher overrides."""
    recipes = [recipe('generic_w8'), recipe('generic_w4', warps=4), recipe('q8_generic_w8', variant=5),
        recipe('tc_m16_s2', backend=1, split=2, tile_m=16, warps=0),
        recipe('tc_m16_s1', backend=1, tile_m=16, warps=0),
        recipe('tc_m8_s1', backend=1, tile_m=8, warps=0),
        recipe('q8_tile16', reader=1, variant=5, values=4, hoist=1),
        recipe('q4_paired32_fixed', reader=2, changes=1, fixed_n=1024, fixed_k=2048),
        recipe('q4_paired16_fixed', reader=3, warps=4, values=4, changes=3, fixed_n=1024, fixed_k=3072)]
    rows, legacy, overrides = [], [], []
    for q in (8, 12):
        for tokens in range(1, 9):
            name = ('q8_generic_w8' if q == 8 else 'generic_w8' if tokens in (1, 4) else
                    'generic_w4' if tokens == 2 else 'tc_m16_s2' if tokens == 3 else
                    'tc_m16_s1' if tokens <= 6 else 'tc_m8_s1')
            legacy.append(dict(q=q, n=512, k=2048, experts=1 if q == 8 else 256,
                               tokens=tokens, compute=int(q == 12), recipe=name))
            contexts = ((1, 0, 0),) if q == 8 else ((1, 0, 1), (2, 1, 2))
            for output, row_order, consumer in contexts:
                body = ('q8_tile16' if q == 8 and tokens == 1 else
                        'q4_paired32_fixed' if q == 12 and tokens == 1 and output == 1 else name)
                rows.append(dict(request=request(q, 512, 2048, tokens, output=output,
                    row_order=row_order, consumer=consumer), recipe=body, evidence='INHERITED_SELECTION'))
    legacy.append(dict(q=8, n=1024, k=3072, experts=1, tokens=1, compute=0, recipe='q8_generic_w8'))
    rows.append(dict(request=request(8, 1024, 3072, 1), recipe='q8_tile16', evidence='INHERITED_SELECTION'))
    for q, n, k, name in ((8, 512, 2048, 'q8_tile16'), (8, 1024, 3072, 'q8_tile16'),
                          (12, 512, 2048, 'q4_paired32_fixed')):
        overrides.append(dict(request=request(q, n, k, 1), recipe=name))
    return dict(recipes=recipes, rows=rows, legacy=legacy, overrides=overrides)


def capture(path):
    from tools.generate_decode_selection import archive, measure
    files = archive(path, ARCHIVE_SHA)
    catalog = inherited_catalog()
    results = []
    for name, expected in (('tp2-chain', 'paired-1'), ('model35-chain', 'paired-shipping')):
        member = 'results/' + name + '.json'
        r = json.loads(files[member])
        if r['status'] != 'PASS' or r['failures'] or r['scope'] != 'FULL_MOE_CHAIN_NOT_MODEL_TPOT':
            raise ValueError('paired-chain result incomplete: ' + name)
        if set(r['numerics']) != {'unfused', 'paired-shipping', 'paired-0', 'paired-1'}:
            raise ValueError('paired-chain numerical arms differ')
        for controls in r['numerics'].values():
            if len(controls) != 30 or {c['tokens'] for c in controls} != set(range(1, 9)):
                raise ValueError('paired-chain numerical coverage differs')
            for c in controls:
                for key in ('activation_error', 'down_error', 'finish_error'):
                    if not math.isfinite(c[key]) or c[key] >= .005:
                        raise ValueError('paired-chain numerical error')
        timing = {arm: measure(value) for arm, value in r['summary'].items()}
        if min(timing, key=lambda a: timing[a]['median_us']) != expected:
            raise ValueError('paired-chain reviewed winner differs')
        results.append(dict(point=name, winner=expected, timing=timing,
            result_sha256=hashlib.sha256(files[member]).hexdigest(),
            scope=r['scope'], numerical_tokens=list(range(1, 9)), policy_tokens=[1]))
    catalog['rows'].append(dict(request=request(12, 512, 3072, 1, consumer_qtype=13, consumer_n=3072),
        recipe='q4_paired16_fixed', evidence='FULL_CHAIN_CONFIRMED'))
    catalog.update(schema='quactlize.gate-up-selection.v2', base_source=BASE_SOURCE,
        archive_sha256=ARCHIVE_SHA, results=results,
        admission='COMPONENT_CONFIRMED_PRODUCTION_ENTRY_PENDING')
    return catalog | dict(sha256=digest(catalog))


def validate(catalog):
    content = {k: v for k, v in catalog.items() if k != 'sha256'}
    if (catalog.get('schema') != 'quactlize.gate-up-selection.v2' or
        catalog.get('archive_sha256') != ARCHIVE_SHA or catalog.get('base_source') != BASE_SOURCE or
        catalog.get('sha256') != digest(content)):
        raise ValueError('paired catalog identity differs; recapture reviewed evidence')
    names = {r['name']: r for r in catalog['recipes']}
    if len(names) != len(catalog['recipes']) or len({r['id'] for r in names.values()}) != len(names):
        raise ValueError('duplicate paired implementation')
    for r in names.values():
        if r['id'] != digest({f: r[f] for f in RECIPE_FIELDS})[:16]:
            raise ValueError('paired recipe body differs')
    keys = set()
    for row in catalog['rows']:
        key = tuple(row['request'][f] for f in REQUEST_FIELDS)
        if key in keys or row['recipe'] not in names:
            raise ValueError('duplicate or unavailable paired choice')
        keys.add(key)
    return names


def header(catalog):
    names = validate(catalog)
    lines = ['// Generated by tools/generate_decode_selection.py. Do not edit.',
             '#ifdef QGU_CATALOG', 'QGU_CATALOG(0x' + catalog['sha256'][:16] + 'ULL)', '#endif',
             '#ifdef QGU_RECIPE', '// name,id,' + ','.join(RECIPE_FIELDS)]
    for r in catalog['recipes']:
        lines.append('QGU_RECIPE(' + r['name'] + ',0x' + r['id'] + 'ULL,' +
                     ','.join(str(r[f]) for f in RECIPE_FIELDS) + ')')
    lines += ['#endif', '#ifdef QGU_RULE', '// recipe,' + ','.join(REQUEST_FIELDS)]
    for row in catalog['rows']:
        lines.append('QGU_RULE(' + row['recipe'] + ',' +
                     ','.join(str(row['request'][f]) for f in REQUEST_FIELDS) + ')')
    lines += ['#endif', '#ifdef QGU_LEGACY', '// recipe,q,N,K,E,tokens,compute']
    for row in catalog['legacy']:
        lines.append('QGU_LEGACY(' + row['recipe'] + ',' +
                     ','.join(str(row[f]) for f in ('q', 'n', 'k', 'experts', 'tokens', 'compute')) + ')')
    lines += ['#endif', '#ifdef QGU_OVERRIDE', '// recipe,' + ','.join(REQUEST_FIELDS[:12])]
    for row in catalog['overrides']:
        lines.append('QGU_OVERRIDE(' + row['recipe'] + ',' +
                     ','.join(str(row['request'][f]) for f in REQUEST_FIELDS[:12]) + ')')
    return '\n'.join(lines + ['#endif', ''])
